import { useEffect, useRef, useState } from 'react';
import { stores } from '../mocks/stores';
import { useParams } from 'react-router-dom';



export default function MenuStickySearch({
    value,
    onChange,
    placeholder = "Search for dishes"
}) {
    const wrapperRef = useRef(null);
    const dropdownRef = useRef(null);
    const [isStoreDropdownOpen, setIsStoreDropdownOpen] = useState(false);
    const { storeId } = useParams();

    // Get current store
    const currentStoreId = storeId || localStorage.getItem('tcr_selected_store') || 'tcr-dlf-cyber-hub';
    const currentStore = stores.find(s => s.id === currentStoreId) || stores[0];

    useEffect(() => {
        const wrapper = wrapperRef.current;
        if (!wrapper) return;

        const updatePosition = () => {
            const headerEl = document.querySelector('header');
            const navHeight = headerEl ? headerEl.offsetHeight : 80;
            wrapper.style.top = `${navHeight}px`;
        };

        // Initial position
        updatePosition();

        // Update on window resize
        window.addEventListener('resize', updatePosition);
        window.addEventListener('scroll', updatePosition);

        return () => {
            window.removeEventListener('resize', updatePosition);
            window.removeEventListener('scroll', updatePosition);
        };
    }, []);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsStoreDropdownOpen(false);
            }
        };

        if (isStoreDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }

        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isStoreDropdownOpen]);

    const handleStoreSelect = (storeId) => {
        localStorage.setItem('tcr_selected_store', storeId);
        setIsStoreDropdownOpen(false);
        // Navigate to menu page with new store
        if (window.REACT_APP_NAVIGATE) {
            window.REACT_APP_NAVIGATE(`/menu/${storeId}`);
        }
    };

    return (
        <div
            ref={wrapperRef}
            className="fixed left-0 right-0 z-40 bg-black/40 backdrop-blur-sm border-t border-b border-cream/20"
        >
            <div className="max-w-[1920px] mx-auto px-8 py-3">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    {/* Left Selector with Dropdown */}
                    <div className="relative" ref={dropdownRef}>
                        <div
                            className="flex items-center group cursor-pointer"
                            onClick={() => setIsStoreDropdownOpen(!isStoreDropdownOpen)}
                        >
                            <div className="w-10 h-10 rounded-full bg-[#C5A021]/10 flex items-center justify-center mr-3 group-hover:bg-[#C5A021]/20 transition-colors">
                                <i className="ri-map-pin-line text-[#C5A021] text-xl"></i>
                            </div>
                            <div>
                                <p className="text-[10px] text-cream/50 font-outfit uppercase tracking-wider">Ordering From</p>
                                <div className="flex items-center gap-2">
                                    <span className="text-cream font-syncopate font-bold text-sm tracking-wide group-hover:text-[#C5A021] transition-colors">
                                        {currentStore.name.toUpperCase()}
                                    </span>
                                    <i className={`ri-arrow-down-s-line text-[#C5A021] text-sm transition-transform ${isStoreDropdownOpen ? 'rotate-180' : ''}`}></i>
                                </div>
                                <p className="text-[10px] text-cream/40 truncate max-w-[200px] font-outfit">{currentStore.address}</p>
                            </div>
                        </div>

                        {/* Store Dropdown */}
                        {isStoreDropdownOpen && (
                            <div className="absolute top-full left-0 mt-2 w-80 bg-obsidian/95 backdrop-blur-md border border-cream/20 rounded-lg shadow-2xl max-h-96 overflow-y-auto z-50">
                                <div className="p-2">
                                    <p className="text-xs text-cream/50 font-outfit uppercase tracking-wider px-3 py-2">Select Store</p>
                                    {stores.map((store) => (
                                        <button
                                            key={store.id}
                                            onClick={() => handleStoreSelect(store.id)}
                                            className={`w-full text-left px-3 py-3 rounded-lg transition-all hover:bg-[#C5A021]/10 ${store.id === currentStoreId ? 'bg-[#C5A021]/20' : ''
                                                }`}
                                        >
                                            <div className="flex items-start justify-between">
                                                <div className="flex-1">
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="font-syncopate text-sm text-cream font-semibold">{store.name}</span>
                                                        {store.status === 'open' ? (
                                                            <span className="text-[10px] px-2 py-0.5 bg-green-500/20 text-green-400 rounded-full font-outfit">Open</span>
                                                        ) : (
                                                            <span className="text-[10px] px-2 py-0.5 bg-red-500/20 text-red-400 rounded-full font-outfit">Closed</span>
                                                        )}
                                                    </div>
                                                    <p className="text-[11px] text-cream/50 font-outfit mb-1">{store.address}</p>
                                                    <div className="flex items-center gap-3 text-[10px] text-cream/40">
                                                        <span className="flex items-center gap-1">
                                                            <i className="ri-time-line"></i>
                                                            {store.timing}
                                                        </span>
                                                        <span className="flex items-center gap-1">
                                                            <i className="ri-map-pin-2-line"></i>
                                                            {store.distance} km
                                                        </span>
                                                    </div>
                                                </div>
                                                {store.id === currentStoreId && (
                                                    <i className="ri-check-line text-[#C5A021] text-lg"></i>
                                                )}
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Right Bar */}
                    <div className="relative w-full md:w-96">
                        <input
                            type="text"
                            className="block w-full pl-4 pr-10 py-2.5 border border-cream/10 rounded-lg leading-5 bg-obsidian/30 text-cream placeholder-cream/40 focus:outline-none focus:bg-obsidian/50 focus:border-[#C5A021]/50 font-outfit text-sm transition-all"
                            placeholder={placeholder}
                            value={value}
                            onChange={(e) => onChange(e.target.value)}
                        />
                        <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                            <i className="ri-search-line text-cream/50 text-lg"></i>
                        </div>
                        {value && (
                            <button
                                aria-label="Clear search"
                                onClick={() => onChange('')}
                                className="absolute inset-y-0 right-10 pr-3 flex items-center text-[#C5A021] hover:text-gold transition pointer-events-auto"
                                type="button"
                            >
                                <i className="ri-close-line text-lg" />
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
